    padding-top: var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    font-size: 0.9rem;
    color: var(--color-text-muted);
}

/* ===== Responsive Design ===== */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .hero {
        grid-template-columns: 1fr;
        padding: var(--spacing-lg) 0;
        gap: var(--spacing-lg);
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-visual {
        min-height: 300px;
    }

    .header-container {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .main-nav {
        width: 100%;
        order: 3;
    }

    .main-nav .nav-list {
        justify-content: flex-start;
        gap: var(--spacing-md);
    }

    .featured-section,
    .deals-section,
    .editorial-section {
        padding: var(--spacing-lg) 0;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .form-group {
        min-width: 100%;
    }

    .footer-grid {
        grid-template-columns: 1fr 1fr;
        gap: var(--spacing-lg);
    }
}

@media (max-width: 480px) {
    :root {
        font-size: 14px;
    }

    h1 {
        font-size: 1.75rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .products-grid,
    .deals-grid,
    .articles-grid {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .header-container {
        padding: var(--spacing-sm);
    }

    .container {
        padding: 0 var(--spacing-sm);
    }
}

/* ===== Forced Colors Support ===== */
@media (forced-colors: active) {
    .site-header,
    .hero,
    .newsletter-section,
    .site-footer {
        border-color: CanvasText;
    }

    .product-card,
    .deal-card,
    .article-card {
        border-color: CanvasText;
    }

    .add-to-cart-btn,
    .cta-button,
    .deal-button,
    .subscribe-button {
        border: 2px solid ButtonBorder;
        forced-color-adjust: none;
    }

    a:focus {
        outline: 3px solid Highlight;
    }

    button:focus {
        outline: 3px solid Highlight;
    }

    .deal-badge {
        background-color: Highlight;
        color: HighlightText;
    }
}

/* ===== Reduced Motion Support ===== */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* ===== Print Styles ===== */
@media print {
    .site-header,
    .site-footer,
    .newsletter-section,
    .icon-button {
        display: none;
    }

    body {
        background: white;
        color: black;
    }

    a {
        color: inherit;
    }

    .product-card,
    .deal-card,
    .article-card {
        page-break-inside: avoid;
    }
}
