/**
 * Setup keyboard navigation for better accessibility
 */
function setupKeyboardNavigation() {
    const navLinks = document.querySelectorAll('.main-nav a');

    navLinks.forEach((link, index) => {
        link.addEventListener('keydown', (e) => {
            let nextLink = null;

            if (e.key === 'ArrowRight' && index < navLinks.length - 1) {
                nextLink = navLinks[index + 1];
            } else if (e.key === 'ArrowLeft' && index > 0) {
                nextLink = navLinks[index - 1];
            } else if (e.key === 'Home') {
                nextLink = navLinks[0];
            } else if (e.key === 'End') {
                nextLink = navLinks[navLinks.length - 1];
            }

            if (nextLink) {
                e.preventDefault();
                nextLink.focus();
            }
        });
    });
}

/**
 * Setup main content focus for skip link
 */
function setupMainContentFocus() {
    const mainContent = document.querySelector('#maincontent');
    if (mainContent) {
        // Make main content focusable programmatically
        mainContent.addEventListener('click', () => {
            mainContent.focus();
        });
    }
}

