/**
 * E-commerce Home Page - Interactive Features
 * Handles user interactions with accessibility in mind
 */

// Cart management
class ShoppingCart {
    constructor() {
        this.items = [];
        this.loadFromStorage();
    }

    addItem(product) {
        const existingItem = this.items.find(item => item.name === product.name);

        if (existingItem) {
            existingItem.quantity += 1;
        } else {
            this.items.push({ ...product, quantity: 1 });
        }

        this.saveToStorage();
        this.notifyUser(`${product.name} added to cart`);
    }

    removeItem(productName) {
        this.items = this.items.filter(item => item.name !== productName);
        this.saveToStorage();
    }

    getTotal() {
        return this.items.reduce((total, item) => total + (item.price * item.quantity), 0);
    }

    saveToStorage() {
        localStorage.setItem('shoppingCart', JSON.stringify(this.items));
    }

    loadFromStorage() {
        const saved = localStorage.getItem('shoppingCart');
        if (saved) {
            this.items = JSON.parse(saved);
        }
    }

    notifyUser(message) {
        // Create or update live region for screen readers
        let liveRegion = document.querySelector('[aria-live="polite"]');
        if (!liveRegion) {
            liveRegion = document.createElement('div');
            liveRegion.setAttribute('aria-live', 'polite');
            liveRegion.setAttribute('aria-atomic', 'true');
            liveRegion.className = 'sr-only';
            document.body.appendChild(liveRegion);
        }

        liveRegion.textContent = message;

        // Also show visual feedback
        this.showNotification(message);
    }

    showNotification(message) {
        const notification = document.createElement('div');
        notification.className = 'notification';
        notification.setAttribute('role', 'status');
        notification.setAttribute('aria-live', 'polite');
        notification.textContent = message;

        document.body.appendChild(notification);

        // Animate in
        requestAnimationFrame(() => {
            notification.classList.add('show');
        });

        // Remove after 3 seconds
        setTimeout(() => {
            notification.classList.remove('show');
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    }
}

// Initialize cart
const cart = new ShoppingCart();

// Add to cart button functionality
document.addEventListener('DOMContentLoaded', () => {
    // Product data
    const products = [
        { name: 'Signature Blazer', price: 285 },
        { name: 'Minimalist Tee', price: 65 },
        { name: 'Midnight Jeans', price: 145 },
        { name: 'Classic Trench', price: 425 }
    ];

    // Attach click handlers to "Add to Cart" buttons
    const addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
    addToCartButtons.forEach((button, index) => {
        if (index < products.length) {
            button.addEventListener('click', (e) => {
                e.preventDefault();
                cart.addItem(products[index]);

                // Visual feedback
                button.textContent = 'Added! ✓';
                button.disabled = true;

                setTimeout(() => {
                    button.textContent = 'Add to Cart';
                    button.disabled = false;
                }, 2000);
            });
        }
    });

    // Newsletter form submission
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();

            const emailInput = document.querySelector('#email-input');
            const email = emailInput.value.trim();

            if (email && isValidEmail(email)) {
                cart.notifyUser(`Thank you! You've been subscribed with ${email}`);
                newsletterForm.reset();
                emailInput.focus();
            } else {
                showError('Please enter a valid email address');
                emailInput.focus();
            }
        });
    }

    // Smooth scroll for navigation links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            const href = this.getAttribute('href');

            // Skip if it's the skip link
            if (href === '#maincontent') {
                return;
            }

            const target = document.querySelector(href);
            if (target) {
                e.preventDefault();
                target.scrollIntoView({ behavior: 'smooth' });

                // Set focus on the target if it's a section
                if (target.id) {
                    target.focus();
                }
            }
        });
    });

    // Shop buttons for deals section
    const dealButtons = document.querySelectorAll('.deal-button');
    dealButtons.forEach(button => {
        button.addEventListener('click', () => {
            const dealName = button.closest('.deal-card').querySelector('h3').textContent;
            cart.notifyUser(`Exploring ${dealName}`);
        });
    });

    // Read article links
    const readMoreLinks = document.querySelectorAll('.read-more');
    readMoreLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const articleTitle = link.closest('.article-card').querySelector('h3').textContent;
            cart.notifyUser(`Reading: ${articleTitle}`);
        });
    });

    // Search button
    const searchButton = document.querySelector('button[aria-label="Search products"]');
    if (searchButton) {
        searchButton.addEventListener('click', () => {
            cart.notifyUser('Search functionality not yet implemented');
        });
    }

    // Setup keyboard navigation for main nav
    setupKeyboardNavigation();

    // Initialize main content focus for skip link
    setupMainContentFocus();
});

/**
 * Setup keyboard navigation for better accessibility
 */
function setupKeyboardNavigation() {
    const navLinks = document.querySelectorAll('.main-nav a');

    navLinks.forEach((link, index) => {
        link.addEventListener('keydown', (e) => {
            let nextLink = null;

            if (e.key === 'ArrowRight' && index < navLinks.length - 1) {
                nextLink = navLinks[index + 1];
            } else if (e.key === 'ArrowLeft' && index > 0) {
                nextLink = navLinks[index - 1];
