 * Responsive navigation toggle for mobile (future enhancement)
 */
function initializeMobileNav() {
    // This can be enhanced with a hamburger menu for smaller screens
    const header = document.querySelector('.site-header');
    const nav = document.querySelector('.main-nav');

    // Detect if nav should be hidden on mobile
    if (window.matchMedia('(max-width: 768px)').matches) {
        // Add mobile-specific enhancements here if needed
    }
}

// Initialize mobile nav
initializeMobileNav();

// Handle window resize
window.addEventListener('resize', () => {
    initializeMobileNav();
});

