:root {
    --color-bg: #0a0a0a;
    --color-bg-secondary: #1a1a1a;
    --color-bg-tertiary: #2a2a2a;
    --color-text: #f5f5f5;
    --color-text-secondary: #b0b0b0;
    --color-text-muted: #808080;
    --color-accent: #d4af37;
    --color-accent-hover: #e5c158;
    --color-border: #333333;
    --color-focus: #a8d5ba;
    --color-error: #ff6b6b;
    --color-success: #51cf66;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --font-family-base: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', sans-serif;
    --font-family-display: 'Georgia', serif;

    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 12px;

    --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.4);
    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.5);
    --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.6);

    --transition: all 0.2s ease-in-out;
}

/* Reset and base styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    background-color: var(--color-bg);
    color: var(--color-text);
    font-family: var(--font-family-base);
    font-size: 16px;
    line-height: 1.6;
    font-weight: 400;
}

/* Screen reader only content */
.sr-only:not(:focus):not(:active) {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-family-display);
    font-weight: 600;
    line-height: 1.2;
    margin-bottom: var(--spacing-md);
    color: var(--color-text);
}

h1 {
    font-size: 3rem;
    letter-spacing: -1px;
}

h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-lg);
}

h3 {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-sm);
}

/* Links */
a {
    color: var(--color-accent);
    text-decoration: none;
    transition: var(--transition);
    outline-offset: 2px;
}

a:hover {
    color: var(--color-accent-hover);
    text-decoration: underline;
}

a:focus {
    outline: 2px solid var(--color-focus);
    border-radius: var(--radius-sm);
}

a:active {
    color: var(--color-accent);
}

/* Buttons */
button {
    font-family: var(--font-family-base);
    font-size: 1rem;
    cursor: pointer;
    border: none;
    transition: var(--transition);
    border-radius: var(--radius-md);
    outline-offset: 2px;
}

button:focus {
    outline: 2px solid var(--color-focus);
}

button:focus:not(:focus-visible) {
    outline: none;
}

button:focus-visible {
    outline: 2px solid var(--color-focus);
}

/* Container */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

/* ===== Header ===== */
.site-header {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-md);
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--spacing-lg);
}

.logo {
    font-family: var(--font-family-display);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-accent);
    letter-spacing: 2px;
    margin: 0;
}

.main-nav .nav-list {
    list-style: none;
    display: flex;
    gap: var(--spacing-lg);
}

.main-nav a {
    font-size: 0.95rem;
    color: var(--color-text);
    text-decoration: none;
    transition: var(--transition);
    position: relative;
    padding-bottom: 4px;
}

.main-nav a:hover {
    color: var(--color-accent);
    text-decoration: none;
}

.main-nav a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width 0.3s ease;
}

.main-nav a:hover::after {
    width: 100%;
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
}

.icon-button {
    background: transparent;
    color: var(--color-text);
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    border-radius: var(--radius-md);
    transition: var(--transition);
    padding: 0;
}

.icon-button:hover {
    background-color: var(--color-bg-tertiary);
    color: var(--color-accent);
}

.icon-button:focus {
    outline: 2px solid var(--color-focus);
}

/* ===== Hero Section ===== */
.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-2xl);
    align-items: center;
    padding: var(--spacing-2xl) 0;
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg) 100%);
    border-bottom: 1px solid var(--color-border);
}

.hero-content {
    padding: var(--spacing-lg);
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: var(--spacing-md);
    color: var(--color-accent);
}

.hero-content p {
    font-size: 1.25rem;
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-lg);
}

.cta-button {
    background-color: var(--color-accent);
    color: var(--color-bg);
    padding: var(--spacing-md) var(--spacing-lg);
    font-size: 1rem;
    font-weight: 600;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: var(--transition);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.cta-button:hover {
    background-color: var(--color-accent-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.cta-button:active {
    transform: translateY(0);
}

.cta-button:focus {
    outline: 2px solid var(--color-focus);
}

.hero-visual {
    position: relative;
    aspect-ratio: 1;
    border-radius: var(--radius-lg);
    overflow: hidden;
    background-color: var(--color-bg-tertiary);
}

.hero-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ===== Featured Products ===== */
.featured-section {
    padding: var(--spacing-2xl) 0;
    border-bottom: 1px solid var(--color-border);
}

.featured-section .container {
    padding: 0 var(--spacing-md);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--color-accent);
    box-shadow: var(--shadow-md);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 3 / 4;
    background-color: var(--color-bg-tertiary);
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
    flex-grow: 1;
}

.product-info h3 {
    margin: 0;
    color: var(--color-text);
}

.product-description {
    color: var(--color-text-secondary);
    font-size: 0.9rem;
    margin: 0;
}

.product-price {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--color-accent);
    margin: var(--spacing-sm) 0;
}

.add-to-cart-btn {
    background-color: var(--color-bg-tertiary);
    color: var(--color-text);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-accent);
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: var(--transition);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 0.5px;
}

.add-to-cart-btn:hover {
    background-color: var(--color-accent);
    color: var(--color-bg);
}

.add-to-cart-btn:active {
    transform: scale(0.98);
}

.add-to-cart-btn:focus {
    outline: 2px solid var(--color-focus);
}

/* ===== Deals Section ===== */
.deals-section {
    padding: var(--spacing-2xl) 0;
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background-color: var(--color-bg-tertiary);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: var(--transition);
    position: relative;
    border: 1px solid var(--color-border);
}

.deal-card:hover {
    border-color: var(--color-accent);
