 * Tests the ecommerce home page with axe-core
 */

const puppeteer = require('puppeteer');
const { AxePuppeteer } = require('@axe-core/puppeteer');

async function runAccessibilityTests() {
  let browser;
  try {
    browser = await puppeteer.launch({
      args: ['--no-sandbox', '--disable-setuid-sandbox'],
      headless: true
    });

    const page = await browser.newPage();

    // Load the local HTML file
    const filePath = `file://${__dirname}/index.html`;
    await page.goto(filePath, { waitUntil: 'networkidle0' });

    // Set viewport to test responsive design
    await page.setViewport({ width: 1280, height: 800 });

    console.log('\n✅ Starting Accessibility Scan...\n');
    console.log(`Testing: ${filePath}\n`);

    // Run axe accessibility audit
    const results = await new AxePuppeteer(page).analyze();

    // Report violations
    console.log('='.repeat(80));
    console.log('ACCESSIBILITY TEST RESULTS');
    console.log('='.repeat(80));

    if (results.violations.length > 0) {
      console.log(`\n❌ ${results.violations.length} Violation(s) Found:\n`);

      results.violations.forEach((violation, index) => {
        console.log(`\n${index + 1}. ${violation.id.toUpperCase()}`);
        console.log(`   Impact: ${violation.impact}`);
        console.log(`   Description: ${violation.description}`);
        console.log(`   Help: ${violation.help}`);
        console.log(`   Affected Elements: ${violation.nodes.length}`);

        violation.nodes.forEach((node, nodeIndex) => {
          console.log(`   - Element ${nodeIndex + 1}: ${node.html.substring(0, 100)}`);
          console.log(`     Impact: ${node.impact}`);
        });
      });
    } else {
      console.log('\n✅ No Violations Found!');
    }

    // Report passes
    console.log(`\n\n✓ ${results.passes.length} Checks Passed`);

    // Report incomplete
    if (results.incomplete.length > 0) {
      console.log(`\n⚠ ${results.incomplete.length} Incomplete Check(s):`);
      results.incomplete.forEach((check) => {
        console.log(`   - ${check.id}: ${check.description}`);
      });
    }

    console.log('\n' + '='.repeat(80));
    console.log(`Total Issues: ${results.violations.length}`);
    console.log('='.repeat(80) + '\n');

    // Return results for analysis
    return results;

  } catch (error) {
    console.error('Test Error:', error);
    process.exit(1);
  } finally {
    if (browser) {
      await browser.close();
    }
  }
}

// Run tests
runAccessibilityTests().then(results => {
  if (results.violations.length > 0) {
    console.log('Run with: npm test');
    process.exit(1);
  } else {
    console.log('✅ All accessibility tests passed!');
    process.exit(0);
  }
});

