      headings.push(level);
    });

    let hierarchyIssue = false;
    for (let i = 1; i < headings.length; i++) {
      if (headings[i] - headings[i - 1] > 1) {
        hierarchyIssue = true;
        break;
      }
    }

    if (!hierarchyIssue && headings.length > 0) {
      passes.push('Heading hierarchy is proper (no skipped levels)');
    } else if (hierarchyIssue) {
      violations.push({
        id: 'heading-order',
        impact: 'moderate',
        description: 'Heading levels should not skip (e.g., H1 to H3)',
        nodes: 1
      });
    }

