      if (!text && !ariaLabel) {
        linksWithoutText++;
      }
    });

    if (linksWithoutText === 0 && links > 0) {
      passes.push(`All ${links} links have descriptive text`);
    } else if (linksWithoutText > 0) {
      violations.push({
        id: 'link-name',
        impact: 'critical',
        description: `${linksWithoutText} link(s) missing descriptive text`,
        nodes: linksWithoutText
      });
    }

